/* @lc app=leetcode id=1703 lang=kotlin */ class Solution { fun minMoves(nums: IntArray, k: Int): Int = nums.indices.filter { nums[it] == 1 }.mapIndexed { i, p -> p - i.toLong() }.let { a -> a.runningFold(0L) { s, x -> s + x }.let { pre -> (0..a.size - k).minOf { i -> (i + k / 2).let { m -> a[m] * (m - i) - (pre[m] - pre[i]) + (pre[i + k] - pre[m + 1]) - a[m] * (i + k - 1 - m) } } } }.toInt() }